def urlencode(items):
    """
    ... 
    """
    if isinstance(items, str) or not hasattr(items, "__iter__"):
        items = [(items,)]

    if isinstance(items, dict):
        items = items.items()

    def quote(string):
        string = str(string)
        return urllib.parse.quote(string, safe="")

    return "&".join([f"{quote(k)}={quote(v)}" for k, v in items])
